import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const m=JSON.parse('{"title":"17｜从一句话需求到需求文档：让 AI 帮你拆需求","description":"","frontmatter":{},"headers":[{"level":2,"title":"应该停下来：AI 帮不了你了","slug":"应该停下来-ai-帮不了你了","link":"#应该停下来-ai-帮不了你了","children":[]},{"level":2,"title":"学习思路","slug":"学习思路","link":"#学习思路","children":[]},{"level":2,"title":"功能描述：Prompt 版本对比","slug":"功能描述-prompt-版本对比","link":"#功能描述-prompt-版本对比","children":[]},{"level":2,"title":"怎么拆才算合格","slug":"怎么拆才算合格","link":"#怎么拆才算合格","children":[{"level":3,"title":"大家做得不好的三个原因","slug":"大家做得不好的三个原因","link":"#大家做得不好的三个原因","children":[]},{"level":3,"title":"需求文档的六维体系","slug":"需求文档的六维体系","link":"#需求文档的六维体系","children":[]},{"level":3,"title":"AI 在六维上的能力地图","slug":"ai-在六维上的能力地图","link":"#ai-在六维上的能力地图","children":[]}]},{"level":2,"title":"怎么用 AI 拆得又快又准","slug":"怎么用-ai-拆得又快又准","link":"#怎么用-ai-拆得又快又准","children":[{"level":3,"title":"Step 1：让 AI 出六维草稿","slug":"step-1-让-ai-出六维草稿","link":"#step-1-让-ai-出六维草稿","children":[]},{"level":3,"title":"Step 2：人补关键三个判断","slug":"step-2-人补关键三个判断","link":"#step-2-人补关键三个判断","children":[]},{"level":3,"title":"Step 3：让 AI 出定稿","slug":"step-3-让-ai-出定稿","link":"#step-3-让-ai-出定稿","children":[]}]},{"level":2,"title":"生成需求文档","slug":"生成需求文档","link":"#生成需求文档","children":[]},{"level":2,"title":"怎么避免最常见的翻车","slug":"怎么避免最常见的翻车","link":"#怎么避免最常见的翻车","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/17｜从一句话需求到需求文档：让AI帮你拆需求.md","filePath":"ClaudeCode企业级老项目改造实战/17｜从一句话需求到需求文档：让AI帮你拆需求.md","lastUpdated":1779815445000}'),l={name:"ClaudeCode企业级老项目改造实战/17｜从一句话需求到需求文档：让AI帮你拆需求.md"};function i(t,s,o,r,c,u){return a(),p("div",null,[...s[0]||(s[0]=[e('<h1 id="_17-从一句话需求到需求文档-让-ai-帮你拆需求" tabindex="-1">17｜从一句话需求到需求文档：让 AI 帮你拆需求 <a class="header-anchor" href="#_17-从一句话需求到需求文档-让-ai-帮你拆需求" aria-label="Permalink to &quot;17｜从一句话需求到需求文档：让 AI 帮你拆需求&quot;">​</a></h1><p>你好，我是 Robert。</p><p>前面我们花了大量的时间讲方法论、讲环境搭建、讲如何建立测试、讲如何铺设护栏。到这里你可能有点着急，怎么还没开始改。我想先分享一个观点： <strong>AI 需要有一套完整的质量保障体系。</strong></p><p>什么是质量保障体系？就是前面讲的那些方法论和流程，它有两个很重要的作用：</p><ol><li><p><strong>保证你改造的下限和质量</strong>。在经验、熟练度、能力等还不够成熟的时候，这套质量保障体系会保证你改造质量的下限，让你的系统不崩，实现小步快走。</p></li><li><p><strong>让你有一个明确的路径去积累和训练个人经验、熟练度、能力等。</strong> 让你达到无视流程、规范也能把老项目改造好的程度，实现大步领跑。</p></li></ol><p>从这一讲开始，我们终于要动手做真实的需求改造了。</p><h2 id="应该停下来-ai-帮不了你了" tabindex="-1">应该停下来：AI 帮不了你了 <a class="header-anchor" href="#应该停下来-ai-帮不了你了" aria-label="Permalink to &quot;应该停下来：AI 帮不了你了&quot;">​</a></h2><p>到这一步，你就应该停下来了，因为 AI 帮不了你了。停下来做什么呢？</p><ol><li><p>把前面生成的架构图和文档都看一遍，理解一遍，然后根据理解再改一遍，给 Claude Code 输入哪里改错了，提示词可以是：“架构图少了一个 MySQL，需要补齐”。</p></li><li><p>自己改完后，最好跟之前负责的同事、团队内的成员过一遍所有的材料。</p></li><li><p>根据你自己的理解和组内成员对这些材料的反馈，让 Claude Code 再改一遍，记得加一句提示词：“同步修改所有相关文档”。</p></li></ol><p>这部分内容最少，但却是最重要的。到了这一步，AI 帮我们把最繁琐的东西都做了一遍了，需要我们接手了。在我的经验中，这一步需要耗费很多时间。坦诚说，这一步我感觉我也教不了你太多，就是上面那三点。而且这一步的质量，决定了之后项目改造的质量，也是体现我们和 AI 有差别的地方。</p><p>如果很好地完成了这一步，项目的文档体系就建立起来了，我们和 AI 对项目的理解可能会达到 70+ 分了，大致了解的级别。接下来就是在不断理解项目、开发项目的过程中加深理解，并且更新文档了。</p><p>好的，我希望你在这一步停个几天，把这些步骤都做完后，我们再继续。</p><p>当你深度理解项目后，我们开始第四部分的学习。</p><h2 id="学习思路" tabindex="-1">学习思路 <a class="header-anchor" href="#学习思路" aria-label="Permalink to &quot;学习思路&quot;">​</a></h2><p>这部分你主要该关注改造思路，也就是怎么改造的，而不是具体改了啥。你要学到的应该是“遇到一个需求/方案/改造任务时，怎么用 AI 把它跑得又快又好”的工作流。</p><p>学这五讲的时候，你可以一边看一边对比：如果是你接到这个需求，你会怎么做？哪些环节你会想到、哪些环节你会漏？我和 AI 跑出来的结果，比你脑子里默认的方法好在哪、差在哪？这种对比，比单纯跟着文稿看收获大十倍。</p><p>这部分我们会以一个完整的真实需求贯穿，给 Spring AI Alibaba Admin 的 Prompt 管理加版本对比功能。</p><h2 id="功能描述-prompt-版本对比" tabindex="-1">功能描述：Prompt 版本对比 <a class="header-anchor" href="#功能描述-prompt-版本对比" aria-label="Permalink to &quot;功能描述：Prompt 版本对比&quot;">​</a></h2><p>解释一下为什么我直接给你这个需求，不做任何铺垫。因为真实业务场景就是这样。leader 或 PM 找到你，开口就是一句话：“给 Prompt 加个版本对比功能”，然后人就走了。</p><p>你的第一反应通常是懵的：什么是版本对比？对比什么？要做到什么程度？给谁用？ <strong>这种“被一句话砸过来、自己心里没底”的状态，就是这一讲要解决的真实场景</strong>。</p><p>解释一下需求：现在 Spring AI Alibaba Admin 里已经有 Prompt 版本管理（POST <code>/api/prompt/version</code> 创建版本、GET <code>/api/prompt/version</code> 取单个版本），但两个版本之间没有 diff 功能。用户想知道 v3 和 v5 改了什么，只能各打开一次自己肉眼对比。</p><p>这个需求有三个特点：</p><ol><li><p><strong>场景真实</strong>。版本对比是版本管理系统的常见缺口，几乎每个有版本概念的系统都会遇到这种需求。</p></li><li><p><strong>改造路径清晰</strong>。一个新接口（GET <code>/api/prompt/version/diff</code>）+ 一段 diff 逻辑 + 前端一个对比按钮和展示组件。涉及后端、前端、测试、文档，是一个完整闭环。</p></li><li><p><strong>真的可以提 PR</strong>。对应仓库目前确实没有这个功能，做完是真能提给 spring-ai-alibaba 项目的。</p></li></ol><p>第四部分的五讲都围绕这个需求展开。17 讲拆需求，18 讲拆方案，19/20 讲分别改后端和前端，21 讲实操课串起来。</p><h2 id="怎么拆才算合格" tabindex="-1">怎么拆才算合格 <a class="header-anchor" href="#怎么拆才算合格" aria-label="Permalink to &quot;怎么拆才算合格&quot;">​</a></h2><p>leader 给你这句话：“给 Prompt 加个版本对比功能”。这句话本身写不了代码，所以得拆。</p><p>拆需求这件事大家都在做，但你回想一下身边的工程师，做出来的需求文档质量差异有多大？同样一个需求，有的人交出来一份接口契约清晰、边界场景齐全、老项目约束都标到位的文档；有的人交出来一份“加个版本对比 + 三行接口签名”的文档就完了。</p><p>这种差异不是技术能力问题，是因为大家都在凭经验做这件事，没体系。状态好就写得全，状态差就漏一半。所以这一讲做两件事：</p><ol><li><p><strong>给一套可重复的体系</strong>，让你每次写出来的需求文档稳定在 80 分以上，不靠状态。</p></li><li><p><strong>教你怎么在老项目场景下用 AI 把这套体系跑得快又准</strong>。既保证下限稳定，又能借 AI 把上限拉到 90 分。</p></li></ol><p>学完这一讲，你会有一份 <code>docs/requirements/prompt-version-diff.md</code>，也是 18 讲的输入。</p><h3 id="大家做得不好的三个原因" tabindex="-1">大家做得不好的三个原因 <a class="header-anchor" href="#大家做得不好的三个原因" aria-label="Permalink to &quot;大家做得不好的三个原因&quot;">​</a></h3><p>讲体系之前，先看看为什么没体系会出问题。这三种翻车情况 90% 的工程师都中过。</p><p><strong>翻车一：写得太抽象</strong>。“加个版本对比功能”，接口签名都没写清楚，错误码、返回结构什么样全靠开发猜。开发拿到要反复跟产品确认，每次确认半天。</p><p><strong>翻车二：漏边界场景</strong>。Happy path 写得完整，但“版本不存在怎么办、两版本完全相同返回什么、内容超长怎么处理”全没列。开发写完测试时才发现要补，又找产品讨论，需求文档反复修改。</p><p><strong>翻车三：忘了老项目约束</strong>。这一条对老项目改造最致命。10 讲讲过 CLAUDE.md 里的禁区和历史包袱。新需求来了，工程师按新需求拆，但忘了“这个 promptKey 已经被 SDK 客户依赖、这个接口路径不能改”。改造做到一半发现踩了禁区，整个返工。</p><p>这三个翻车背后是同一个问题： <strong>没有可重复的体系，每次靠经验拍脑袋</strong>。下面给体系。</p><h3 id="需求文档的六维体系" tabindex="-1">需求文档的六维体系 <a class="header-anchor" href="#需求文档的六维体系" aria-label="Permalink to &quot;需求文档的六维体系&quot;">​</a></h3><p>把需求文档拆成六个维度，每次拆需求都按这六个维度跑一遍。 <strong>这不是发明新方法论，是把工程师本来就在做的事结构化</strong>。好处是每次产出格式一致、不漏维度、团队 review 起来快。而这就是 AI 最擅长的事情。</p><blockquote><p>Tips：你后面是不是可以考虑把下面的六个维度写成 Skill 落地下来。</p></blockquote><ol><li><p><strong>业务目标</strong>：一句话说清楚解决什么问题、给谁用。例：让用户快速看出 Prompt 两个版本之间的差异，定位是哪次改动引入了问题。</p></li><li><p><strong>用户场景</strong>：典型使用场景 + 当前痛点 + 期望体验。比抽象的业务目标更具体。例：工程师调试 Prompt 时切换版本看效果，目前只能各打开一次肉眼对比，期望一键对比。</p></li><li><p><strong>接口契约</strong>：方法、路径、入参、返回、错误码。开发拿到这一节就能写代码。</p></li><li><p><strong>边界场景清单</strong>：异常情况和它们的预期处理。空值、超长、不存在、并发、跨范围……每条都要有“预期行为”。</p></li><li><p><strong>老项目约束</strong>（ <strong>新项目没有，老项目独有</strong>）：CLAUDE.md 禁区和历史包袱里和这个需求相关的条目。新增接口要避开禁区、新功能要兼容历史包袱。</p></li><li><p><strong>不在这次范围里的事</strong>：明确这次不做什么。“对比两个版本”扩展开可能变成“对比 N 版本”、“对比附评分”、“导出 diff”，不写“不做这些”，AI 就会顺手给你做了。</p></li></ol><p>六个维度合起来就是一份完整的文档，开发拿了能直接写代码、测试拿了能直接补用例、产品拿了能直接 review。下面我们看看 AI 在这六维上分别能干到什么程度。</p><h3 id="ai-在六维上的能力地图" tabindex="-1">AI 在六维上的能力地图 <a class="header-anchor" href="#ai-在六维上的能力地图" aria-label="Permalink to &quot;AI 在六维上的能力地图&quot;">​</a></h3><p>这是 17 讲的核心。 <strong>AI 不是替你拆需求，是和你分工</strong>。看清 AI 在每个维度上的真实能力，分工才合理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/ebcd12378c67c3e8138ff9e9647a3914.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/ebcd12378c67c3e8138ff9e9647a3914.png" alt="图片"></a></p><p><strong>AI 强的维度（85+ 分）</strong>：</p><ul><li><p><strong>接口契约</strong>。基于 docs/api-list.md 和现有代码，AI 能写出和现有接口风格一致的契约。错误码沿用项目惯例、统一返回结构对、参数命名风格一致。人手写要查现有接口模仿，AI 30 秒搞定。</p></li><li><p><strong>边界场景的技术性 edge case</strong>。404、空值、超长、并发、不存在……这些技术 edge case AI 列得很全。AI 比人想得全，因为 AI 没疲劳。</p></li><li><p><strong>老项目约束</strong>。基于 CLAUDE.md 和现有代码反推。这一项 AI 比工程师强得多，人凭脑子记不住 CLAUDE.md 全文，AI 每次启动都加载全部内容。</p></li></ul><p><strong>AI 中等的维度（60 分左右）</strong>：</p><ul><li><p><strong>业务目标</strong>。AI 能从代码反推一个版本，但容易写偏方向。比如 AI 写“帮工程师调试不同版本”，但你的真实目标是“给运营看 Prompt 演进”，方向就错了。草稿能用做起点，但方向必须人定。</p></li><li><p><strong>用户场景</strong>。AI 能根据接口推测使用场景，但真实痛点 AI 不知道。草稿能用做起点，但具体痛点要你补。</p></li></ul><p><strong>AI 弱的维度（30 分以下）</strong>：</p><ul><li><p><strong>边界场景的产品决策</strong>。AI 能列“内容超长怎么办”这种场景，但这种场景该怎么处理是产品决策：截断显示？返回 400？提示用户？AI 不知道你的产品判断。</p></li><li><p><strong>不在这次范围里的事</strong>。完全是产品判断。AI 默认会写“做对比”含糊一片，它不知道你的优先级和资源。</p></li></ul><p><strong>心法一句话：AI 帮你做 AI 强的（70%），人补 AI 弱的（30%），整体出来 90+</strong>。下面三步走，教你怎么跑这个分工。</p><h2 id="怎么用-ai-拆得又快又准" tabindex="-1">怎么用 AI 拆得又快又准 <a class="header-anchor" href="#怎么用-ai-拆得又快又准" aria-label="Permalink to &quot;怎么用 AI 拆得又快又准&quot;">​</a></h2><h3 id="step-1-让-ai-出六维草稿" tabindex="-1">Step 1：让 AI 出六维草稿 <a class="header-anchor" href="#step-1-让-ai-出六维草稿" aria-label="Permalink to &quot;Step 1：让 AI 出六维草稿&quot;">​</a></h3><p>第一步把 AI 强的维度先压满。提示词的关键是把“读 docs/、读 CLAUDE.md、读现有代码”这三件事强制让 AI 做。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我有一个新需求：给 Prompt 管理加版本对比功能。</span></span>\n<span class="line"><span>GET /api/prompt/version/diff?promptKey=xxx&amp;versionA=v3&amp;versionB=v5</span></span>\n<span class="line"><span>返回两个版本的 diff 结果。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>读 docs/ 下的所有资产（特别是 api-list.md、data-model.md、CLAUDE.md），</span></span>\n<span class="line"><span>再扫一下代码里现有 Prompt 版本相关的实现（PromptVersionController、</span></span>\n<span class="line"><span>PromptService、PromptVersionEntity），按以下六个维度给我写需求文档草稿：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. 业务目标（一句话）</span></span>\n<span class="line"><span>2. 用户场景（典型使用场景 + 当前痛点）</span></span>\n<span class="line"><span>3. 接口契约（方法、路径、入参、返回、错误码，对齐项目现有风格）</span></span>\n<span class="line"><span>4. 边界场景清单（至少列 8 条 edge case，包括从现有代码反推的，</span></span>\n<span class="line"><span>   每条标&quot;待产品决策&quot;或基于现有代码的预期行为）</span></span>\n<span class="line"><span>5. 老项目约束（CLAUDE.md 禁区和历史包袱里和这个需求相关的，</span></span>\n<span class="line"><span>   每条标 CLAUDE.md 来源）</span></span>\n<span class="line"><span>6. 不在这次范围里的事（先列你能想到的候选，最终我来定）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>输出 markdown，保存到 docs/requirements/prompt-version-diff.md。</span></span></code></pre></div><p><strong>关键约束</strong>：</p><ul><li>强制读 docs/ + CLAUDE.md + 现有代码（把老项目隐性知识显性化）</li><li>单独列“老项目约束”维度（强迫 AI 显式输出禁区和历史包袱）</li><li>边界场景至少 8 条 + 每条标“预期行为”或“待产品决策”（防止 AI 偷懒只列 happy path）</li><li>“不在这次范围里” AI 先列候选，人后定（AI 提供候选，决策权在人）</li></ul><p>产出：一份六维结构齐全的草稿，覆盖 70% 内容。我在 Spring AI Alibaba Admin 上跑了一遍，AI 真实跑出来的草稿大概长这样（节选关键两段）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/68c9b71f49ea053b276de10de5ee2f77.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/68c9b71f49ea053b276de10de5ee2f77.png" alt="图片"></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/4e14294705d531c96baf6642e93afb62.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/978446/4e14294705d531c96baf6642e93afb62.png" alt="图片"></a></p><p>注意几个细节：</p><p><strong>老项目约束这一节，三条都有 CLAUDE.md 来源</strong>。AI 不是泛泛说要遵守约束，是把每一条具体到哪一节、影响什么、怎么对齐。这种细节，工程师手写时 90% 会忘。</p><p><strong>边界场景实际列了 12 条</strong>（这里只截了 5 条）。AI 不光列了基础场景（不存在、相同），还列出了只有读了代码才知道的场景：JPA <code>@Table</code> 的字段为 null（E04）、LONGTEXT 字段超大（E10）、MySQL collation 大小写敏感性（E11）。这些场景 AI 是从 entity 类、SQL 建表语句、DB 配置反推的，人凭脑子想想不到这么细。</p><p><strong>每条边界都标了“基于代码推断”或“待产品决策”</strong>。基于代码推断的，AI 给出明确预期行为；待产品决策的，AI 老老实实标出来等你定。这种透明度比 AI 自作主张拍板要好得多。</p><h3 id="step-2-人补关键三个判断" tabindex="-1">Step 2：人补关键三个判断 <a class="header-anchor" href="#step-2-人补关键三个判断" aria-label="Permalink to &quot;Step 2：人补关键三个判断&quot;">​</a></h3><p>草稿覆盖了 70%，剩下 30% 必须人补。 <strong>只 review 三个判断</strong>：</p><ol><li><p>业务目标的方向</p></li><li><p>边界场景的产品决策</p></li><li><p>不在这次范围里的事</p></li></ol><p>其他维度（接口契约、技术边界、老项目约束）AI 写的直接用。为什么只补这三个？前面能力地图里讲过： <strong>AI 在数据和代码层面强，在业务判断层面弱</strong>。这三个判断都是业务判断，AI 永远做不了。</p><p>回到我们的真实需求，三个判断我是这么决策的：</p><p><strong>判断一：业务目标修正</strong>：AI 草稿默认偏“工程师 review 自己的修改”，但对照三个场景里有两个是团队场景（线上效果回溯、多人协作合并），真实目标更偏“团队多人协作下的 Prompt 演进追溯”。这个调整决定了 diff 结果要返回元信息（创建时间、状态），不只是内容。</p><p><strong>判断二：5 条待决策边界场景</strong>：E04 <code>template</code> 为 <code>null</code> 视同空字符串、E07 软删除的 Prompt 允许查 diff、E10 不做大小限制、E11 不在应用层 toLowerCase（DB 默认不敏感）、E12 不加缓存。</p><p><strong>判断三：8 条候选范围决策</strong>：7 条砍掉、2 条留到下期。砍掉的包括后端生成 unified diff、跨 promptKey 对比、N 版本对比、缓存等；留到下期的是 diff 导出、一键比对上一版。</p><p>判断都做完后，把决策反馈给 AI 让它整理出定稿。下一步给 AI 的提示词在 Step 3。</p><h3 id="step-3-让-ai-出定稿" tabindex="-1">Step 3：让 AI 出定稿 <a class="header-anchor" href="#step-3-让-ai-出定稿" aria-label="Permalink to &quot;Step 3：让 AI 出定稿&quot;">​</a></h3><p>把 Step 2 的三个判断打包反馈给 AI，让它一次性更新到文档里：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我对 docs/requirements/prompt-version-diff.md 做了三个判断，</span></span>\n<span class="line"><span>按下面的内容更新文档：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>业务目标修正：从&quot;工程师 review 自己的修改&quot;改成&quot;团队多人协作下的</span></span>\n<span class="line"><span>Prompt 演进追溯&quot;。diff 结果要返回 versionA/versionB 的元信息</span></span>\n<span class="line"><span>（创建时间、状态）不只是内容。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>边界场景的产品决策（每条更新到表格里替换&quot;待产品决策&quot;）：</span></span>\n<span class="line"><span>- E04（template 为 null）：null 视同空字符串</span></span>\n<span class="line"><span>- E07（已软删除）：允许查 diff</span></span>\n<span class="line"><span>- E10（LONGTEXT 超大）：本期不做大小限制</span></span>\n<span class="line"><span>- E11（版本号大小写）：不在应用层 toLowerCase</span></span>\n<span class="line"><span>- E12（高并发）：本期不加缓存</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>不在这次范围里的事最终决策：</span></span>\n<span class="line"><span>- 砍掉：后端生成 unified diff、跨 promptKey 对比、N 版本对比、</span></span>\n<span class="line"><span>  diff 缓存、versionDescription diff、权限控制</span></span>\n<span class="line"><span>- 留到下期：diff 导出、一键比对上一版</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>整理为正式技术文档：</span></span>\n<span class="line"><span>- 一句话总结放最前</span></span>\n<span class="line"><span>- 接口契约用表格（方法 + 路径 + 入参 + 返回 + 错误码）</span></span>\n<span class="line"><span>- 边界场景用表格（场景 + 预期行为 + 依据）</span></span>\n<span class="line"><span>- 老项目约束单独一节，每条标 CLAUDE.md 来源</span></span>\n<span class="line"><span>- 不在这次范围里的事单独一节</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>保存到原文件。</span></span></code></pre></div><p>这个提示词有点长，但是你会发现内容是模板化的，你可以尝试在自己的项目中去使用这个模板，看看效果。来看产出：定稿的 <code>docs/requirements/prompt-version-diff.md</code>。整个三步跑下来 20 分钟，Step 1 让 AI 跑五分钟、Step 2 你做三个判断十分钟、Step 3 让 AI 整理五分钟，比手写 PRD 省两个小时。</p><h2 id="生成需求文档" tabindex="-1">生成需求文档 <a class="header-anchor" href="#生成需求文档" aria-label="Permalink to &quot;生成需求文档&quot;">​</a></h2><p>下面就是生成的需求文档，很标准了。标准的原因就是前面模板化的提示词。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Prompt 版本对比（Diff）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; 状态：正式</span></span>\n<span class="line"><span>&amp;gt; 创建时间：2026-04-27</span></span>\n<span class="line"><span>&amp;gt; 关联接口：`GET /api/prompt/version/diff`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**一句话总结：** 在团队多人协作下，支持任意两个 Prompt 版本的内容与元信息对比，用于演进追溯和发布前 review。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 1. 业务目标</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>支持团队多人协作场景下的 Prompt 演进追溯：任意两个版本之间的 `template`、`variables`、`modelConfig` 内容差异，以及版本元信息（创建时间、状态、创建者），均可通过一次接口调用获取，无需手动切换版本页面对比。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 2. 用户场景</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**场景 A — 发布前 review**</span></span>\n<span class="line"><span>工程师修改了 `customer-service` v4 → v5，准备发布到生产。PM 需要核对改了哪些地方，目前只能在两个版本详情页之间反复切换，手动比对 `template` 内容。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**场景 B — 问题回溯**</span></span>\n<span class="line"><span>线上 Prompt `order-summary` 在 v7 之后效果下滑，工程师需要逐版本比对，找到是哪一次修改引入了问题。当前没有 diff 视图，只能在本地手动 diff。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**场景 C — 多人协作冲突解决**</span></span>\n<span class="line"><span>两名工程师各自基于 v3 创建了 v4-alice 和 v4-bob，需要对比差异后决定合并策略。返回的版本元信息（创建时间、状态）帮助团队判断哪个版本更新、哪个已发布。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**当前痛点：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `GET /api/prompt/version` 每次只返回单个版本，没有跨版本比较视图</span></span>\n<span class="line"><span>- `PromptVersionDO.previousVersion` 字段已存在（设计时预留 diff 场景），但从未被任何接口消费</span></span>\n<span class="line"><span>- 版本列表接口不返回 `template` 内容，用户须逐个请求详情再手动比对</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 3. 接口契约</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 基本信息</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 项 | 值 |</span></span>\n<span class="line"><span>| --- | --- |</span></span>\n<span class="line"><span>| 方法 | `GET` |</span></span>\n<span class="line"><span>| 路径 | `/api/prompt/version/diff` |</span></span>\n<span class="line"><span>| 鉴权 | `Authorization: Bearer &amp;lt;token&amp;gt;`（与其他 `/api/prompt/*` 接口一致） |</span></span>\n<span class="line"><span>| 返回格式 | `Result&amp;lt;PromptVersionDiffResult&amp;gt;` |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 入参</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 参数名 | 类型 | 必填 | 约束 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- | --- | --- |</span></span>\n<span class="line"><span>| `promptKey` | `String` | ✅ | `&amp;#64;NotBlank`；`^[a-zA-Z0-9_-]+$`；长度 1–255 | 与 `PromptCreateRequest.promptKey` 校验规则一致 |</span></span>\n<span class="line"><span>| `versionA` | `String` | ✅ | `&amp;#64;NotBlank`；`^[a-zA-Z0-9._-]+$`；长度 1–32 | 与 `PromptVersionCreateRequest.version` 校验规则一致 |</span></span>\n<span class="line"><span>| `versionB` | `String` | ✅ | `&amp;#64;NotBlank`；`^[a-zA-Z0-9._-]+$`；长度 1–32 | 同上 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**示例：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```http</span></span>\n<span class="line"><span>GET /api/prompt/version/diff?promptKey=customer-service&amp;versionA=v3&amp;versionB=v5</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 返回结构</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**顶层：** `Result&amp;lt;PromptVersionDiffResult&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 字段 | 类型 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `code` | `Integer` | 200 = 成功 |</span></span>\n<span class="line"><span>| `message` | `String` | `&quot;success&quot;` 或错误描述 |</span></span>\n<span class="line"><span>| `data` | `PromptVersionDiffResult` | diff 结果，见下表 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**`PromptVersionDiffResult`：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 字段 | 类型 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `promptKey` | `String` | 被比较的 Prompt Key |</span></span>\n<span class="line"><span>| `versionA` | `VersionMeta` | 版本 A 元信息 |</span></span>\n<span class="line"><span>| `versionB` | `VersionMeta` | 版本 B 元信息 |</span></span>\n<span class="line"><span>| `diffs` | `DiffFields` | 各字段的对比结果 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**`VersionMeta`（版本元信息）：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 字段 | 类型 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `version` | `String` | 版本号 |</span></span>\n<span class="line"><span>| `status` | `String` | `pre` / `release` |</span></span>\n<span class="line"><span>| `createTime` | `Long` | 创建时间，epoch 毫秒，与现有 `PromptVersionDetail.createTime` 格式一致 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**`DiffFields`：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 字段 | 类型 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `template` | `DiffItem` | Prompt 模板内容对比 |</span></span>\n<span class="line"><span>| `variables` | `DiffItem` | 变量列表对比 |</span></span>\n<span class="line"><span>| `modelConfig` | `DiffItem` | 模型参数对比 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**`DiffItem`：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 字段 | 类型 | 说明 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `changed` | `Boolean` | 两版本该字段是否有差异（null 视同空字符串参与比较） |</span></span>\n<span class="line"><span>| `valueA` | `String` | 版本 A 的原始字符串值；字段为 null 时返回 `&quot;&quot;` |</span></span>\n<span class="line"><span>| `valueB` | `String` | 版本 B 的原始字符串值；字段为 null 时返回 `&quot;&quot;` |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; **设计说明：** 接口返回原始字段值，不在后端生成行级 diff 标注。行级高亮由前端渲染层实现，后端不持有 UI 表达逻辑。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**响应示例：**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```json</span></span>\n<span class="line"><span>{</span></span>\n<span class="line"><span>  &quot;code&quot;: 200,</span></span>\n<span class="line"><span>  &quot;message&quot;: &quot;success&quot;,</span></span>\n<span class="line"><span>  &quot;data&quot;: {</span></span>\n<span class="line"><span>    &quot;promptKey&quot;: &quot;customer-service&quot;,</span></span>\n<span class="line"><span>    &quot;versionA&quot;: {</span></span>\n<span class="line"><span>      &quot;version&quot;: &quot;v3&quot;,</span></span>\n<span class="line"><span>      &quot;status&quot;: &quot;release&quot;,</span></span>\n<span class="line"><span>      &quot;createTime&quot;: 1745000000000</span></span>\n<span class="line"><span>    },</span></span>\n<span class="line"><span>    &quot;versionB&quot;: {</span></span>\n<span class="line"><span>      &quot;version&quot;: &quot;v5&quot;,</span></span>\n<span class="line"><span>      &quot;status&quot;: &quot;pre&quot;,</span></span>\n<span class="line"><span>      &quot;createTime&quot;: 1745100000000</span></span>\n<span class="line"><span>    },</span></span>\n<span class="line"><span>    &quot;diffs&quot;: {</span></span>\n<span class="line"><span>      &quot;template&quot;: {</span></span>\n<span class="line"><span>        &quot;changed&quot;: true,</span></span>\n<span class="line"><span>        &quot;valueA&quot;: &quot;你是一名客服，请回答用户问题。\\n\\n用户问题：{​{question}​}&quot;,</span></span>\n<span class="line"><span>        &quot;valueB&quot;: &quot;你是一名专业客服，请简洁准确地回答用户问题。\\n\\n用户问题：{​{question}​}\\n\\n要求：回答不超过200字。&quot;</span></span>\n<span class="line"><span>      },</span></span>\n<span class="line"><span>      &quot;variables&quot;: {</span></span>\n<span class="line"><span>        &quot;changed&quot;: false,</span></span>\n<span class="line"><span>        &quot;valueA&quot;: &quot;[\\&quot;question\\&quot;]&quot;,</span></span>\n<span class="line"><span>        &quot;valueB&quot;: &quot;[\\&quot;question\\&quot;]&quot;</span></span>\n<span class="line"><span>      },</span></span>\n<span class="line"><span>      &quot;modelConfig&quot;: {</span></span>\n<span class="line"><span>        &quot;changed&quot;: true,</span></span>\n<span class="line"><span>        &quot;valueA&quot;: &quot;&amp;#123;\\&quot;temperature\\&quot;: 0.7, \\&quot;maxTokens\\&quot;: 1024&amp;#125;&quot;,</span></span>\n<span class="line"><span>        &quot;valueB&quot;: &quot;&amp;#123;\\&quot;temperature\\&quot;: 0.3, \\&quot;maxTokens\\&quot;: 512&amp;#125;&quot;</span></span>\n<span class="line"><span>      }</span></span>\n<span class="line"><span>    }</span></span>\n<span class="line"><span>  }</span></span>\n<span class="line"><span>}</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 错误码</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| HTTP 状态码 | `code` | `message` | 触发条件 |</span></span>\n<span class="line"><span>| --- | --- | --- | --- |</span></span>\n<span class="line"><span>| 400 | 400 | `&quot;参数错误：{字段} 不能为空&quot;` | `promptKey`/`versionA`/`versionB` 为空或格式不符 |</span></span>\n<span class="line"><span>| 400 | 400 | `&quot;versionA 和 versionB 不能相同&quot;` | 两个版本号完全相同 |</span></span>\n<span class="line"><span>| 404 | 404 | `&quot;Prompt 不存在&quot;` | `promptKey` 在 DB 中不存在 |</span></span>\n<span class="line"><span>| 404 | 404 | `&quot;版本 {versionA} 不存在&quot;` | 版本 A 在该 `promptKey` 下找不到 |</span></span>\n<span class="line"><span>| 404 | 404 | `&quot;版本 {versionB} 不存在&quot;` | 版本 B 在该 `promptKey` 下找不到 |</span></span>\n<span class="line"><span>| 500 | 500 | `&quot;An internal error has occurred...&quot;` | 未预期异常 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; 错误码与 `StudioException` 常量对齐：`INVALID_PARAM=400`、`NOT_FOUND=404`、`SERVER_ERROR=500`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 4. 边界场景</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| # | 场景 | 预期行为 | 依据 |</span></span>\n<span class="line"><span>| --- | --- | --- | --- |</span></span>\n<span class="line"><span>| E01 | `versionA == versionB`（传入相同版本号） | 返回 400，`&quot;versionA 和 versionB 不能相同&quot;` | 所有字段 `changed=false` 无业务意义，且大概率是调用方 bug；代码推断 |</span></span>\n<span class="line"><span>| E02 | `promptKey` 存在，但某个版本不存在 | 返回 404，错误信息明确区分是 versionA 还是 versionB 不存在，如 `&quot;版本 v9 不存在&quot;` | 方便前端精确提示；代码推断 |</span></span>\n<span class="line"><span>| E03 | `promptKey` 本身不存在 | 先查 `prompt` 表，返回 404 `&quot;Prompt 不存在&quot;`，不继续查版本表 | 快速失败，减少无效 DB 查询；代码推断 |</span></span>\n<span class="line"><span>| E04 | 某版本的 `template` / `variables` / `modelConfig` 为 null（历史数据缺失） | null 视同空字符串：`valueA`/`valueB` 返回 `&quot;&quot;`，`changed` 基于空字符串参与比较 | **产品决策** |</span></span>\n<span class="line"><span>| E05 | `versionA` 和 `versionB` 属于不同 `promptKey` | 接口设计只有一个 `promptKey`，两版本必须属于同一 Prompt；传入版本号在当前 `promptKey` 下查不到时走 E02 的 404 逻辑 | 跨 Prompt 比较不在本期范围；代码推断 |</span></span>\n<span class="line"><span>| E06 | 两个版本都是 `pre` 状态，或一个 `release` 一个 `pre` | 正常返回，不限制版本状态组合 | `pre` 版本之间的 diff 是合理的 review 场景；代码推断 |</span></span>\n<span class="line"><span>| E07 | `promptKey` 对应的 Prompt 已被软删除 | 允许查 diff，正常返回版本内容 | 历史追溯需要；**产品决策** |</span></span>\n<span class="line"><span>| E08 | `template` 内容极大（LONGTEXT，可达数 MB） | 直接返回完整内容，本期不做大小限制；网络传输性能由调用方承担 | **产品决策** |</span></span>\n<span class="line"><span>| E09 | 版本号大小写，如 `versionA=V3` vs 存储值 `v3` | 不在应用层做 toLowerCase；查询结果依赖 MySQL collation（`admin` 库 `utf8mb4_general_ci`，大小写不敏感），行为与现有 `GET /api/prompt/version` 一致 | **产品决策** |</span></span>\n<span class="line"><span>| E10 | 高并发对同一对版本频繁请求 diff | 纯只读接口，DB 读并发安全；本期不加缓存 | **产品决策** |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 5. 老项目约束</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 约束 | CLAUDE.md 来源 | 对本需求的影响 |</span></span>\n<span class="line"><span>| --- | --- | --- |</span></span>\n<span class="line"><span>| `prompt_version` 表使用 **JPA `&amp;#64;Table`**，实体在 `server-start/entity` 包 | &quot;ORM 混用&quot; | 新查询逻辑必须走 JPA Repository 或 JPQL，不能混用 MyBatis-Plus `BaseMapper`；新 DTO `PromptVersionDiffResult` 不加 `&amp;#64;TableName` |</span></span>\n<span class="line"><span>| 接口传参和关联外键一律用**业务 ID**，不暴露自增主键 | &quot;业务 ID vs 自增主键&quot; | 入参使用 `promptKey + versionA + versionB`，禁止用数据库 `id` 字段作为查询条件 |</span></span>\n<span class="line"><span>| 大多数表用 `status = 0` 表示软删除，直接写 `DELETE` 会破坏数据完整性 | &quot;逻辑删除&quot; | `prompt_version` 当前无 `deleted` 字段；E07 决策允许查已软删除 Prompt 的版本，查询时不过滤 `prompt.status`，仅按 `prompt_key` 查版本表 |</span></span>\n<span class="line"><span>| 统一返回结构：`Result&amp;lt;T&amp;gt; { code, message, data: T }` | &quot;统一返回结构&quot; | `PromptVersionDiffResult` 必须包在 `Result&amp;lt;&amp;gt;` 里返回；错误时用 `Result.error(code, message)`，不裸抛 HTTP 异常 |</span></span>\n<span class="line"><span>| `admin` 库用 JPA，`agentscope` 库用 MyBatis-Plus，注意 DataSource 路由 | &quot;ORM 混用&quot; | `prompt_version` 在 `admin` 库，diff 接口只读 `admin` 库，无跨库操作风险 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 6. 不在这次范围里</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 本期砍掉（不做）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 候选项 | 原因 |</span></span>\n<span class="line"><span>| --- | --- |</span></span>\n<span class="line"><span>| 后端生成 unified diff / Myers diff 行级标注 | diff 格式与前端 UI 框架强耦合，前端自行计算性能更好；后端不持有渲染逻辑 |</span></span>\n<span class="line"><span>| 跨 `promptKey` 的版本对比 | 业务语义不清晰，`promptKey` 是版本的命名空间，跨 key 比较无明确含义 |</span></span>\n<span class="line"><span>| 超过 2 个版本的多向对比（v3 vs v4 vs v5） | 界面复杂度指数级增加，当前场景不需要 |</span></span>\n<span class="line"><span>| Diff 结果缓存（Redis） | 当前数据量小；缓存带来的失效一致性问题得不偿失，量上来再做 |</span></span>\n<span class="line"><span>| `versionDescription` 字段的 diff | 非核心内容，改动频率低，意义不大 |</span></span>\n<span class="line"><span>| 细粒度权限控制（仅创建者可查 diff） | 当前无细粒度资源权限体系，等权限体系完善后再加 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 留到下期</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 候选项 | 说明 |</span></span>\n<span class="line"><span>| --- | --- |</span></span>\n<span class="line"><span>| Diff 结果导出（PDF / 文本文件下载） | 有审计存档场景，非 MVP 必须 |</span></span>\n<span class="line"><span>| 基于 `previousVersion` 的&quot;一键比对上一版&quot;快捷入口 | `PromptVersionDO.previousVersion` 字段已存在，后端接口已通用（调用方传 `versionA=previousVersion` 即可）；前端加快捷按钮即可，不需要新增后端接口 |</span></span></code></pre></div><blockquote><p>Tips：你可以把这份文档复制到本地 markdown 文件查看，应该可以看到不少内容。</p></blockquote><p>review 重点：接口契约能直接给后端用吗？边界场景每条都有明确的预期行为吗？老项目约束每条都有 CLAUDE.md 来源标注吗？</p><h2 id="怎么避免最常见的翻车" tabindex="-1">怎么避免最常见的翻车 <a class="header-anchor" href="#怎么避免最常见的翻车" aria-label="Permalink to &quot;怎么避免最常见的翻车&quot;">​</a></h2><p>老项目拆需求最大的翻车点是这个： <strong>AI 草稿覆盖 70% 看起来挺全，工程师跳过 Step 2 直接用</strong>。为什么这是致命错误？</p><p>AI 草稿的 70% 集中在 AI 强的维度（接口契约、技术边界、老项目约束），看起来很完整。剩下 30% 恰好是 AI 弱的维度（业务方向、产品决策、改造范围）。</p><p>跳过 Step 2 → AI 弱的维度凭它的默认理解填 → 业务方向偏、范围模糊、产品决策错位 → 改造做完业务方说“不是我要的”。</p><p>记住一个数字：AI 帮你做到 70 分， <strong>人 review 补的 30 分是这份文档从能用到好用的关键</strong>。</p><p>呼应 15 讲讲过的“AI 写测试的隐性偏差”：那一讲讲 AI 用业务直觉补测试断言，错；这一讲讲 AI 用代码默认填业务目标和产品决策，错。 <strong>两讲背后是同一个心法：AI 在数据和代码层面强，在业务判断层面弱</strong>。和 AI 分工，不要把 AI 当定稿——这是这一讲最硬的一句话。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲的内容比较多，也比较繁琐。其实就想强调一个观点：我们已经到了改造的深水区了，需要我们进一步深入介入了，这一步千万不能偷懒。在我看来，这一步做的好坏与否，就是老项目改造效果好与不好的最重要原因。</p><p>总结一下这一讲的核心： <strong>给一套需求文档六维体系，让你在老项目场景下用 AI 把它跑得又快又准</strong>。</p><ol><li><p>六个维度：业务目标、用户场景、接口契约、边界场景、老项目约束、不在这次范围里的事。</p></li><li><p>AI 能力地图：接口契约、技术边界、老项目约束 AI 强（85+），业务目标、用户场景 AI 中（60），产品决策、改造范围 AI 弱（30 以下）。</p></li><li><p>三步走：AI 出 70 分草稿（基于 docs/ + CLAUDE.md + 现有代码）→ 人补三个关键判断（业务方向 + 产品决策 + 范围）→ AI 出定稿。全程 20 分钟。</p></li><li><p>最容易翻车的点：把 AI 草稿当定稿。AI 强的部分覆盖 70%，但漏的 30% 才是文档从能用到好用的关键。这 30% 必须人补。</p></li></ol><p>下一讲我们拿着这份需求文档，开始拆改造方案：涉及哪些代码、改哪些地方、用什么 diff 库、改造任务怎么排，把“做什么”翻译成“怎么做”。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你拿过的需求文档里最让你头疼的是哪个维度？业务目标、边界场景、还是不做的事？这个维度让你头疼的原因是写的人没写清楚，还是你没追问清楚？</p></li><li><p>想象你接下来一个月要写 5 份需求文档，AI 帮你把每份从 2 小时压到 20 分钟，省下 8 个多小时。这 8 小时你会拿来做什么，多做一个需求、多做 review、还是其他？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>',96)])])}const g=n(l,[["render",i]]);export{m as __pageData,g as default};
